const CACHE='folio-v1-20260916';
const FILES=['./','./index.html','./styles.css','./app.js','./parsers.js','./storage.js','./forge.js','./favicon.svg','./vendor/jszip.min.js','./vendor/purify.min.js','./vendor/pdf.mjs','./vendor/pdf.worker.mjs','./fonts/be-vietnam-regular.ttf','./fonts/be-vietnam-semibold.ttf'];
self.addEventListener('install',e=>e.waitUntil(caches.open(CACHE).then(c=>c.addAll(FILES))));
self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('folio-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',event=>{const url=new URL(event.request.url);if(event.request.method!=='GET'||url.origin!==self.location.origin)return;const known=FILES.some(f=>new URL(f,self.registration.scope).pathname===url.pathname)||url.pathname.startsWith(new URL('./vendor/',self.registration.scope).pathname);if(!known)return;event.respondWith(fetch(event.request).then(response=>{if(response.ok&&!response.redirected){const clone=response.clone();caches.open(CACHE).then(c=>c.put(event.request,clone));}return response;}).catch(()=>caches.match(event.request)));});
